/* National Genomic Test Directory Explorer. Data: data/directory.js (TDX) and data/panels.js (TDX_PANELS), both
 * generated by tools/update-explorer.py. Routes: #R133 (indication), #gene=BRCA1 (gene), #q=… (search). */
(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const IND = TDX.indications;
  const BY_CODE = Object.fromEntries(IND.map(e => [e.code, e]));
  const PANELS = (typeof TDX_PANELS !== 'undefined' && TDX_PANELS.panels) || {};
  const PANELS_DATE = typeof TDX_PANELS !== 'undefined' ? TDX_PANELS.date : '';
  const PANELAPP = id => `https://panelapp.genomicsengland.co.uk/panels/${id}/`;
  const pdfPage = p => `${TDX.meta.pdfUrl}#page=${p}`;
  const plural = (n, w, ws = w + 's') => `${n} ${n === 1 ? w : ws}`;
  const cmp = (a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
  const uniq = xs => [...new Map(xs.filter(Boolean).map(x => [x.toLowerCase(), x])).values()].sort(cmp);

  // Genes, STRs and regions on each indication's panels (green only), and every panel a gene is on.
  const panelEntities = id => { const p = PANELS[id]; return p ? [...p.genes, ...(p.strs || []), ...(p.regions || [])] : []; };
  const GENE_INDEX = {};
  for (const e of IND) for (const t of e.tests) for (const id of t.panels) for (const g of panelEntities(id)) {
    const k = g.toUpperCase(); (GENE_INDEX[k] = GENE_INDEX[k] || { name: g, tests: new Set() }).tests.add(t.id);
  }
  // A gene named in the target text without a panel (e.g. "CFTR", "SMN1") also counts.
  const NOT_GENES = /^(CNVS?|STRS?|WGS|WES|DNA|UPD|MLPA|PWS|AS|NIPD|LHON|FISH|CI)$/;
  for (const e of IND) for (const t of e.tests) for (const w of t.target.match(/\b[A-Z][A-Z0-9-]{1,9}\b/g) || []) {
    if (NOT_GENES.test(w) || !(GENE_INDEX[w] || /\d/.test(w) || t.target.trim() === w)) continue;
    (GENE_INDEX[w] = GENE_INDEX[w] || { name: w, tests: new Set() }).tests.add(t.id);
  }
  const testById = Object.fromEntries(IND.flatMap(e => e.tests.map(t => [t.id, { ...t, ind: e }])));

  // Abbreviations (abbreviations.js): marked in the rendered text; the meaning shows on hover, tap or keyboard focus.
  // A few letters mean different things on different indications (TDX_ABBR_BY_CODE); gene symbols in a test's target are left alone.
  const ABBR = typeof TDX_ABBR !== 'undefined' ? TDX_ABBR : {};
  const ABBR_LOCAL = typeof TDX_ABBR_BY_CODE !== 'undefined' ? TDX_ABBR_BY_CODE : {};
  const abbrRe = keys => new RegExp(`(^|[^A-Za-z0-9])(${keys.sort((a, b) => b.length - a.length)
    .map(k => k.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')).join('|')})(?![A-Za-z0-9])`, 'g');
  const ABBR_RE = { '': abbrRe(Object.keys(ABBR)) };
  const abbrDict = code => ABBR_LOCAL[code] ? { ...ABBR, ...ABBR_LOCAL[code] } : ABBR;
  const abbrRegex = code => ABBR_LOCAL[code] ? (ABBR_RE[code] = ABBR_RE[code] || abbrRe(Object.keys(abbrDict(code)))) : ABBR_RE[''];
  const ABBR_SKIP = 'script,style,select,option,input,textarea,abbr,.genes,.no-abbr,.visually-hidden,#abbr-tip';
  function markAbbr(root, code = '') {
    const dict = abbrDict(code), re = abbrRegex(code), found = new Set();
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT), hits = [];
    for (let n; (n = walker.nextNode());) {
      const el = n.parentElement;
      if (!el || !/[A-Z]{2}|[a-z][A-Z]/.test(n.nodeValue) || el.closest(ABBR_SKIP)) continue;
      re.lastIndex = 0;
      if (re.test(n.nodeValue)) hits.push(n);
    }
    for (const n of hits) {
      const inTarget = n.parentElement.closest('.target');
      const html = esc(n.nodeValue).replace(re, (m, pre, k) => {
        if (inTarget && GENE_INDEX[k.toUpperCase()]) return m;
        found.add(k);
        return `${pre}<abbr class="abbr" title="${esc(dict[k])}" data-full="${esc(dict[k])}">${k}</abbr>`;
      });
      const t = document.createElement('template'); t.innerHTML = html; n.replaceWith(t.content);
    }
    // Keyboard users can reach the abbreviations on an indication or gene page (not inside links, which take focus themselves).
    root.querySelectorAll('#detail abbr.abbr:not([tabindex])').forEach(a => { if (!a.closest('a, button, summary')) a.tabIndex = 0; });
    return [...found].sort(cmp).map(k => [k, dict[k]]);
  }

  // Filters: clinical area (Part of the criteria document), method, commissioning, requesting specialty.
  const partSort = p => { const m = /^([IVXL]+)\s/.exec(p); if (!m) return 99; const v = { I: 1, V: 5, X: 10, L: 50 }; let n = 0;
    [...m[1]].forEach((c, i, a) => { n += v[c] < (v[a[i + 1]] || 0) ? -v[c] : v[c]; }); return n; };
  const partName = p => p.replace(/^[IVXL]+\s+/, '');
  const FILTERS = {
    part: { label: 'Clinical area', values: [...new Set(IND.map(e => e.part))].sort((a, b) => partSort(a) - partSort(b)), of: e => [e.part], show: partName },
    method: { label: 'Test method', values: uniq(IND.flatMap(e => e.tests.map(t => t.method))), of: e => e.tests.map(t => t.method) },
    commissioning: { label: 'Commissioning', values: uniq(IND.flatMap(e => e.tests.map(t => t.commissioning))), of: e => e.tests.map(t => t.commissioning) },
    specialty: { label: 'Requesting specialty', values: uniq(IND.flatMap(e => e.specialties || [])), of: e => e.specialties || [] },
  };
  const state = { q: '', part: '', method: '', commissioning: '', specialty: '', changed: false };

  // Search: every word must match somewhere; rank exact code, then name, then gene/target, then criteria text.
  const textOf = e => [e.name, ...(e.criteria || []).map(c => c[2]), ...(e.overlapping || []), e.pathway, ...(e.specialties || [])].join(' \n ');
  const words = q => q.trim().split(/\s+/).filter(Boolean);
  const wordRe = w => new RegExp(`(^|[^A-Za-z0-9])${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i');
  // Tests with smaller panels are more specific for a gene, so they rank higher (0–20 points).
  const specificity = tests => Math.max(...tests.map(t => { const n = t.panels.reduce((a, id) => a + panelEntities(id).length, 0) || 1;
    return Math.round(20 * (1 - Math.log(n) / Math.log(5000))); }));
  function match(e, ws) {
    if (!ws.length) return { score: 0, why: '' };
    let score = 0; const why = [];
    for (const w of ws) {
      const re = wordRe(w), W = w.toUpperCase();
      if (e.code.toUpperCase() === W || e.tests.some(t => t.id.toUpperCase() === W)) { score += 1000; continue; }
      if (re.test(e.name)) { score += 100; continue; }
      const g = GENE_INDEX[W], hit = g && e.tests.filter(t => g.tests.has(t.id));
      if (hit && hit.length) { score += 50 + specificity(hit); why.push(`${g.name} is tested by ${hit.map(t => t.id).join(', ')}`); continue; }
      if (e.tests.some(t => re.test(t.target) || re.test(t.method))) { score += 30; why.push(`test target or method mentions “${w}”`); continue; }
      const txt = textOf(e);
      if (re.test(txt)) { const n = txt.split(re).length - 1; score += Math.min(n, 10); why.push(`criteria mention “${w}”`); continue; }
      return null;
    }
    return { score, why: [...new Set(why)].join('; ') };
  }
  function results() {
    const ws = words(state.q);
    return IND.map(e => ({ e, m: match(e, ws) }))
      .filter(({ e, m }) => m && Object.keys(FILTERS).every(k => !state[k] || FILTERS[k].of(e).some(v => v.toLowerCase() === state[k].toLowerCase()))
        && (!state.changed || e.change))
      .sort((a, b) => (b.m.score - a.m.score) || cmp(a.e.code, b.e.code));
  }

  // Shared bits of markup.
  const linkCodes = s => esc(s).replace(/\b(R\d{1,3})(\.\d+)?\b/g, (m, c) => BY_CODE[c] ? `<a href="#${c}">${m}</a>` : m);
  const chip = (s, cls = '') => `<span class="chip ${cls}">${esc(s)}</span>`;
  const methods = e => uniq(e.tests.map(t => t.method)).map(m => chip(m)).join('');
  function panelBlock(t) {
    if (!t.panels.length) return '';
    return t.panels.map(id => {
      const p = PANELS[id];
      if (!p) return `<p class="small muted">Panel ${id} was not found in PanelApp when this page was built. <a class="ext" href="${PANELAPP(id)}" target="_blank" rel="noopener">Try PanelApp</a></p>`;
      const ents = panelEntities(id);
      const list = p.genes.length ? `<p class="genes">${p.genes.map(g => `<a href="#gene=${encodeURIComponent(g)}">${esc(g)}</a>`).join(' ')}</p>` : '';
      const extra = [p.strs && `STRs: ${p.strs.join(', ')}`, p.regions && `Regions: ${p.regions.join(', ')}`].filter(Boolean).map(x => `<p class="small">${esc(x)}</p>`).join('');
      return `<div class="panel"><p class="panel-name"><a class="ext" href="${PANELAPP(id)}" target="_blank" rel="noopener">${esc(p.name)} on PanelApp<span class="visually-hidden"> (opens in a new tab)</span></a>
        <span class="muted small">panel ${id} · version ${esc(p.version)} used here</span></p>
        <details><summary>Show the ${plural(ents.length, 'green gene or locus', 'green genes and loci')}</summary>${list}${extra}</details></div>`;
    }).join('');
  }
  // Links to the original documents so the details can be double-checked.
  function sourcesBox(e) {
    const panels = [...new Set(e.tests.flatMap(t => t.panels))];
    const links = [
      e.page && `<li><a class="ext" href="${pdfPage(e.page)}" target="_blank" rel="noopener">Eligibility criteria ${esc(TDX.meta.criteria)} – PDF page ${e.page}</a>
        <span class="muted small">opens at the page in most browsers</span></li>`,
      `<li><a class="ext" href="${esc(TDX.meta.xlsxUrl)}">Test Directory spreadsheet ${esc(TDX.meta.directory)}</a> <span class="muted small">download; find ${e.code} in the “R&amp;ID indications” tab</span></li>`,
      ...panels.map(id => `<li><a class="ext" href="${PANELAPP(id)}" target="_blank" rel="noopener">${esc(PANELS[id] ? PANELS[id].name : 'Panel ' + id)} on PanelApp</a>
        <span class="muted small">panel ${id}${PANELS[id] ? `, gene list (version ${esc(PANELS[id].version)} used here)` : ' – not found when this page was built'}</span></li>`),
    ].filter(Boolean);
    return `<section class="sources" aria-labelledby="src-title"><h3 id="src-title">Check the sources</h3><ul>${links.join('')}</ul>
      <p class="small muted">PanelApp shows the panel's current version, which may have changed since ${esc(PANELS_DATE || 'this page was built')}.</p></section>`;
  }
  function testCard(t) {
    const rows = [['Target', `<span class="target">${esc(t.target)}</span>`], ['Method', esc(t.method)], ['Optimal family structure', esc(t.family)],
      ['Scope', esc(t.scope)], ['Commissioning', esc(t.commissioning)], ['Specialist test group', esc(t.group)],
      ['Change since last version', t.change ? esc(t.change) : '']].filter(r => r[1]);
    return `<article class="test" id="${esc(t.id)}"><h4><span class="code">${esc(t.id)}</span> ${esc(t.method)}</h4>
      <dl>${rows.map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${panelBlock(t)}</article>`;
  }
  const critList = items => `<ul class="crit-list">${items.map(([lv, mk, tx]) =>
    `<li class="lv${lv}${!mk && (/:$/.test(tx) && tx.length < 90 || /^Testing Criteria for /.test(tx)) ? ' crit-sub' : ''}">${mk ? `<span class="mk">${esc(mk)}</span> ` : ''}${linkCodes(tx)}</li>`).join('')}</ul>`;
  const bulletList = xs => xs && xs.length ? `<ul>${xs.map(x => `<li>${linkCodes(x)}</li>`).join('')}</ul>` : '<p class="muted">Not stated</p>';

  // The abbreviations on a page, listed at the end (useful on touch screens and when printed).
  function glossary(list) {
    if (!list.length) return;
    $('#detail').insertAdjacentHTML('beforeend', `<details class="block glossary no-abbr"><summary>Abbreviations on this page (${list.length})</summary>
      <dl>${list.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></details>`);
  }

  // Views.
  function renderHome() {
    document.title = 'Test Directory Explorer';
    const list = results(), shown = list.slice(0, 400);
    const W = state.q.trim().toUpperCase(), gene = GENE_INDEX[W];
    $('#count').textContent = `${plural(list.length, 'clinical indication')} of ${IND.length}`;
    $('#gene-hint').innerHTML = gene ? `<a href="#gene=${encodeURIComponent(gene.name)}">${esc(gene.name)}</a> is tested by ${plural(gene.tests.size, 'test')} – <a href="#gene=${encodeURIComponent(gene.name)}">see them all</a>` : '';
    $('#gene-hint').hidden = !gene;
    $('#results').innerHTML = shown.length ? shown.map(({ e, m }) => `<li><a class="row" href="#${e.code}">
        <span class="row-head"><span class="code">${e.code}</span> <span class="row-name">${esc(e.name)}</span>${e.change ? ' <span class="chip changed">Changed in this version</span>' : ''}</span>
        <span class="row-meta">${esc(partName(e.part))} · ${plural(e.tests.length, 'test')} ${methods(e)}</span>
        ${m.why ? `<span class="row-why">${esc(m.why)}</span>` : ''}</a></li>`).join('')
      : '<li class="empty">No clinical indications match. Try fewer words or clear the filters.</li>';
    markAbbr($('#results'));
    show('home');
  }
  function renderIndication(code) {
    const e = BY_CODE[code];
    if (!e) return notFound(code);
    document.title = `${e.code} ${e.name} – Test Directory Explorer`;
    const variants = Object.entries(e.variants || {}).map(([v, x]) => `<section class="block"><h3>${esc(v)}</h3>
      ${x['Where in Pathway'] ? `<p><strong>Where in pathway:</strong> ${esc(x['Where in Pathway'])}</p>` : ''}
      ${x['Requesting Specialties'] ? `<p><strong>Requesting specialties:</strong> ${esc(x['Requesting Specialties'].join(', '))}</p>` : ''}</section>`).join('');
    $('#detail').innerHTML = `<p class="back"><a href="#${state.q ? 'q=' + encodeURIComponent(state.q) : ''}">← All clinical indications</a></p>
      <h2 id="detail-title"><span class="code">${e.code}</span> ${esc(e.name)}</h2>
      <p class="meta">${uniq([partName(e.part), e.group]).map(x => chip(x)).join(' ')} ${e.change ? chip('Changed: ' + e.change, 'changed') : ''}</p>
      ${sourcesBox(e)}
      <div class="cols">
        <div>
          <section class="block"><h3>Testing criteria</h3>
            ${e.page ? `<p class="small"><a class="ext" href="${pdfPage(e.page)}" target="_blank" rel="noopener">Check in the PDF (page ${e.page})<span class="visually-hidden"> (opens in a new tab)</span></a></p>` : ''}
            ${e.criteria ? critList(e.criteria) : '<p class="muted">Not found in the eligibility criteria document.</p>'}
            ${e.page ? `<p class="small source">Quoted from the <a class="ext" href="${pdfPage(e.page)}" target="_blank" rel="noopener">eligibility criteria ${esc(TDX.meta.criteria)}, PDF page ${e.page}</a>.</p>` : ''}
          </section>
          ${e.overlapping && e.overlapping.length ? `<section class="block"><h3>Overlapping indications</h3>${bulletList(e.overlapping)}</section>` : ''}
        </div>
        <div>
          <section class="block"><h3>${plural(e.tests.length, 'test')}</h3>${e.tests.map(testCard).join('')}</section>
          <section class="block"><h3>Who can request it</h3>
            <p><strong>Where in pathway:</strong> ${e.pathway ? esc(e.pathway) : '<span class="muted">Not stated</span>'}</p>
            <p><strong>Requesting specialties</strong></p>${bulletList(e.specialties)}
            ${e.specialtyNotes ? `<p class="small">${e.specialtyNotes.map(esc).join('<br>')}</p>` : ''}
            <p><strong>Specialist service group:</strong> ${esc((e.serviceGroup || []).join(', ')) || '<span class="muted">Not stated</span>'}</p>
          </section>
          ${variants}
        </div>
      </div>`;
    glossary(markAbbr($('#detail'), e.code));
    show('detail');
  }
  function renderGene(name) {
    const g = GENE_INDEX[name.toUpperCase()];
    if (!g) return notFound(name, true);
    document.title = `${g.name} – Test Directory Explorer`;
    const tests = [...g.tests].map(id => testById[id]).sort((a, b) => cmp(a.id, b.id));
    $('#detail').innerHTML = `<p class="back"><a href="#${state.q ? 'q=' + encodeURIComponent(state.q) : ''}">← All clinical indications</a></p>
      <h2 id="detail-title" class="no-abbr">${esc(g.name)}</h2>
      <p>Tested by ${plural(tests.length, 'test')} in ${plural(new Set(tests.map(t => t.ind.code)).size, 'clinical indication')}: green on the test's PanelApp panel, or named in its target.
        <a href="https://panelapp.genomicsengland.co.uk/panels/entities/${encodeURIComponent(g.name)}" target="_blank" rel="noopener">${esc(g.name)} in PanelApp</a></p>
      <ul class="results">${tests.map(t => `<li class="row"><a class="row-head" href="#${t.ind.code}"><span class="code">${esc(t.id)}</span> <span class="row-name">${esc(t.ind.name)}</span></a>
        <span class="row-meta"><span class="target">${esc(t.target)}</span> ${chip(t.method)}</span>
        ${t.panels.length ? `<span class="row-meta">${t.panels.map(id => `<a class="ext" href="${PANELAPP(id)}" target="_blank" rel="noopener">${esc(PANELS[id] ? PANELS[id].name : 'Panel ' + id)} on PanelApp</a>`).join(' · ')}</span>` : ''}
        ${t.ind.page ? `<span class="row-meta"><a class="ext" href="${pdfPage(t.ind.page)}" target="_blank" rel="noopener">${esc(t.ind.code)} criteria – PDF page ${t.ind.page}</a></span>` : ''}</li>`).join('')}</ul>`;
    glossary(markAbbr($('#detail')));
    show('detail');
  }
  function notFound(what, gene) {
    document.title = 'Not found – Test Directory Explorer';
    $('#detail').innerHTML = `<p class="back"><a href="#">← All clinical indications</a></p><h2 id="detail-title">Not found</h2>
      <p>${esc(what)} is not ${gene ? 'tested by any test' : 'a clinical indication'} in the National Genomic Test Directory ${esc(TDX.meta.directory)}.</p>`;
    show('detail');
  }
  function show(which) {
    $('#home').hidden = which !== 'home'; $('#detail').hidden = which !== 'detail';
    if (which === 'detail') { window.scrollTo(0, 0); $('#detail-title').setAttribute('tabindex', '-1'); $('#detail-title').focus({ preventScroll: true }); }
  }
  function route() {
    const h = decodeURIComponent(location.hash.slice(1));
    let m;
    if ((m = /^(R\d+)(?:\.\d+)?$/i.exec(h))) return renderIndication(m[1].toUpperCase());
    if ((m = /^gene=(.+)$/.exec(h))) return renderGene(m[1]);
    if ((m = /^q=(.*)$/.exec(h))) { state.q = m[1]; $('#q').value = state.q; }
    renderHome();
  }

  // Set up the page.
  $('#stats').textContent = `${IND.length} clinical indications · ${IND.reduce((n, e) => n + e.tests.length, 0)} tests · ${Object.keys(GENE_INDEX).length.toLocaleString()} genes and loci`;
  $('#version').innerHTML = `Test Directory <a href="${esc(TDX.meta.xlsxUrl)}">${esc(TDX.meta.directory)}</a>, eligibility criteria
    <a href="${esc(TDX.meta.pdfUrl)}">${esc(TDX.meta.criteria)}</a>${PANELS && TDX_PANELS.date ? `, PanelApp ${esc(TDX_PANELS.date)}` : ''}.`;
  $('#filters').insertAdjacentHTML('afterbegin', Object.entries(FILTERS).map(([k, f]) => `<label>${f.label}
    <select id="f-${k}" data-filter="${k}"><option value="">All</option>${f.values.map(v => `<option value="${esc(v)}">${esc((f.show || String)(v))}</option>`).join('')}</select></label>`).join(''));
  const fromHome = () => { if (location.hash && !/^#q=/.test(location.hash)) history.pushState(null, '', '#'); renderHome(); };
  let t; // debounce timer for the search box
  $('#q').addEventListener('input', () => {
    state.q = $('#q').value; clearTimeout(t);
    t = setTimeout(() => { history.replaceState(null, '', state.q.trim() ? '#q=' + encodeURIComponent(state.q.trim()) : location.pathname); fromHome(); }, 150);
  });
  $('#search').addEventListener('submit', ev => {
    ev.preventDefault(); const W = $('#q').value.trim().toUpperCase();
    clearTimeout(t);
    if (/^R\d{1,3}(\.\d+)?$/.test(W) && BY_CODE[W.split('.')[0]]) location.hash = W.split('.')[0];
  });
  $('#filters').addEventListener('change', ev => {
    const k = ev.target.dataset.filter;
    if (k) state[k] = ev.target.value; else if (ev.target.id === 'f-changed') state.changed = ev.target.checked;
    fromHome();
  });
  $('#clear').addEventListener('click', () => {
    Object.keys(FILTERS).forEach(k => { state[k] = ''; $(`#f-${k}`).value = ''; });
    state.changed = false; $('#f-changed').checked = false; state.q = ''; $('#q').value = '';
    history.replaceState(null, '', location.pathname); renderHome(); $('#q').focus();
  });
  // Abbreviation tooltip: shows at once on hover, keyboard focus or tap (tap again or press Escape to close).
  const tip = document.createElement('div');
  tip.id = 'abbr-tip'; tip.setAttribute('role', 'tooltip'); tip.hidden = true;
  document.body.append(tip);
  let tipFor = null;
  const showTip = el => {
    if (el.title) el.removeAttribute('title'); // the meaning stays in data-full; avoids a second, slow browser tooltip
    tip.textContent = el.dataset.full; tip.hidden = false; tipFor = el; placeTip();
  };
  const placeTip = () => {
    const r = tipFor.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
    if (r.bottom < 0 || r.top > innerHeight) return hideTip();
    tip.style.left = `${Math.max(8, Math.min(r.left + r.width / 2 - w / 2, innerWidth - w - 8))}px`;
    tip.style.top = `${r.bottom + 6 + h > innerHeight ? r.top - h - 6 : r.bottom + 6}px`;
  };
  const hideTip = () => { tip.hidden = true; tipFor = null; };
  // A tap also fires mouseover and focus before its click, which would open the tooltip early; so a tap decides
  // from whether this word's tooltip was open when the finger went down (open: close it; closed: open it).
  let touching = false, openAtPress = null;
  document.addEventListener('pointerdown', ev => { touching = ev.pointerType !== 'mouse'; openAtPress = tipFor; }, true);
  document.addEventListener('pointermove', ev => { if (ev.pointerType === 'mouse') touching = false; }, true);
  document.addEventListener('mouseover', ev => {
    if (touching) return;
    const el = ev.target.closest && ev.target.closest('abbr.abbr'); if (el) showTip(el); else if (tipFor) hideTip();
  });
  document.addEventListener('focusin', ev => { const el = ev.target.closest && ev.target.closest('abbr.abbr'); if (el) showTip(el); else if (tipFor) hideTip(); });
  document.addEventListener('click', ev => {
    const el = ev.target.closest && ev.target.closest('abbr.abbr');
    if (!el) { if (tipFor) hideTip(); return; }
    if (el.closest('a, button, summary, label')) return; // links keep working; hovering still shows the meaning
    ev.preventDefault();
    if (ev.pointerType !== 'mouse' && openAtPress === el) hideTip(); else showTip(el);
  }, true);
  addEventListener('scroll', () => { if (tipFor) placeTip(); }, { passive: true }); // follows the word; hides once it is off screen
  document.addEventListener('keydown', ev => { if (ev.key === 'Escape' && tipFor) hideTip(); });
  markAbbr(document.querySelector('footer'));
  markAbbr(document.querySelector('.intro'));

  window.addEventListener('hashchange', route);
  route();
})();
